// adoptPendingReviewMarkerInto reads any pending review marker and, if present,
// tags the given session state as a review session. The marker is cleared
// on successful adoption so subsequent sessions start clean.
func adoptPendingReviewMarkerInto(s session.State) (session.State, error) {
    m, ok, err := ReadPendingReviewMarker()
    if err != nil {
        return s, err
    }
    if !ok {
        return s, nil
    }
    s.Kind = session.KindReview
    s.ReviewStatus = session.ReviewStatusInProgress
    s.ReviewSkills = m.Skills
    if err := ClearPendingReviewMarker(); err != nil {
        // Log and continue — tagging succeeded; leftover marker self-heals
        // on next session start (will re-adopt, then re-clear; idempotent).
        logging.Warn(context.Background(), "failed to clear pending review marker", "err", err)
    }
    return s, nil
}
```

Wire it into the turn-start / session-initialization path so that every new session checks for the marker. Because `Kind` is only set when the marker exists, normal sessions are unaffected.

