package claudecode

import (
    "context"
    "fmt"
    "os"
    "os/exec"
)

// LaunchCmd builds an exec.Cmd for `claude "<initialPrompt>"`. Stdio is wired
// to the caller's TTY so the agent runs foreground and the user interacts
// normally. The call site is expected to Run() and wait.
func (c *ClaudeCode) LaunchCmd(ctx context.Context, initialPrompt string) (*exec.Cmd, error) {
    bin, err := exec.LookPath("claude")
    if err != nil {
        return nil, fmt.Errorf("claude binary not on PATH: %w", err)
    }
    cmd := exec.CommandContext(ctx, bin, initialPrompt)
    cmd.Stdin = os.Stdin
    cmd.Stdout = os.Stdout
    cmd.Stderr = os.Stderr
    cmd.Env = os.Environ() // inherit; hooks pick up ENTIRE_* vars
    return cmd, nil
}
