// runReviewConfigPicker presents a huh multi-select for each installed agent
// and saves the selection to .entire/settings.json. Returns the picked
// configuration so callers can proceed immediately without re-reading.
func runReviewConfigPicker(ctx context.Context, out io.Writer) (map[string][]string, error) {
    installed := GetAgentsWithHooksInstalled(ctx)
    if len(installed) == 0 {
        return nil, fmt.Errorf("no agents installed; run 'entire enable' first")
    }
    selected := map[string][]string{}
    for _, agentName := range installed {
        curated, ok := curatedReviewSkills[string(agentName)]
        if !ok || len(curated) == 0 {
            continue // agent has no curated list; user must edit JSON manually
        }
        var picks []string
        options := make([]huh.Option[string], 0, len(curated))
        for _, s := range curated {
            options = append(options, huh.NewOption(fmt.Sprintf("%s — %s", s.Name, s.Desc), s.Name))
        }
        form := NewAccessibleForm(huh.NewGroup(
            huh.NewMultiSelect[string]().
                Title(fmt.Sprintf("Pick review skills for %s", agentName)).
                Options(options...).
                Value(&picks),
        ))
        if err := form.Run(); err != nil {
            return nil, fmt.Errorf("picker for %s: %w", agentName, err)
        }
        if len(picks) > 0 {
            selected[string(agentName)] = picks
        }
    }
    if len(selected) == 0 {
        return nil, fmt.Errorf("no review skills selected")
    }
    if err := saveReviewConfig(ctx, selected); err != nil {
        return nil, err
    }
    fmt.Fprintf(out, "Saved review config to .entire/settings.json. Edit directly or run `entire review --edit`.\n")
    return selected, nil
}

// saveReviewConfig persists the review map into .entire/settings.json.
// Preserves all other settings.
func saveReviewConfig(ctx context.Context, review map[string][]string) error {
    s, err := settings.Load(ctx)
    if err != nil {
        s = &settings.EntireSettings{}
    }
    s.Review = review
    return settings.Save(ctx, s) // assumes a Save helper exists — if not, add one
}
