func promptReviewFallback(ctx context.Context, cmd *cobra.Command, sessionID string) error {
    var choice string
    form := NewAccessibleForm(huh.NewGroup(
        huh.NewSelect[string]().
            Title("Review session ended. What's next?").
            Options(
                huh.NewOption("Fix   — run `entire resume` after to continue", "fix"),
                huh.NewOption("Close — commit review marker now", "close"),
                huh.NewOption("Skip  — end without committing", "skip"),
            ).
            Value(&choice),
    ))
    if err := form.Run(); err != nil {
        return err
    }
    switch choice {
    case "fix":
        return finalizeFix(ctx, cmd, sessionID)
    case "close":
        return finalizeClose(ctx, cmd, sessionID)
    case "skip":
        return finalizeSkip(ctx, cmd, sessionID)
    }
    return nil
}
```

